// Package itemsstore implements the items
// interfaces with queries generated by sqlc. The generated code lives in
// package sqlcgen; edit queries.sql and regenerate it instead of editing it.
package itemsstore

import (
	"context"
	"fmt"

	"example.com/shop/internal/items"
	"example.com/shop/internal/items/itemsstore/sqlcgen"
)

// itemStore is a items.ItemStore backed by sqlc queries.
type itemStore struct {
	q *sqlcgen.Queries
}

// New returns a items.ItemStore that stores items in db.
func New(db sqlcgen.DBTX) items.ItemStore {
	return &itemStore{q: sqlcgen.New(db)}
}

func (s *itemStore) List(ctx context.Context) ([]items.Item, error) {
	rows, err := s.q.ListItems(ctx)
	if err != nil {
		return nil, fmt.Errorf("list items: %w", err)
	}
	list := make([]items.Item, len(rows))
	for i, row := range rows {
		list[i] = toModel(row)
	}
	return list, nil
}

func (s *itemStore) Create(ctx context.Context, name string) (items.Item, error) {
	row, err := s.q.CreateItem(ctx, name)
	if err != nil {
		return items.Item{}, fmt.Errorf("create item: %w", err)
	}
	return toModel(row), nil
}

func toModel(row sqlcgen.Item) items.Item {
	return items.Item{ID: row.ID, Name: row.Name, CreatedAt: row.CreatedAt}
}
